const app=document.querySelector('#app');
const {levels,generate,advance}=GardenMath;
function read(key){try{const n=Number(localStorage.getItem(key));return Number.isFinite(n)?Math.max(0,Math.floor(n)):0;}catch{return 0;}}
function save(key,value){try{localStorage.setItem(key,String(value));}catch{}}
let stars=read('garden-stars'),savedLevel=Math.min(levels.length-1,read('garden-level'));
let selected=savedLevel,round=0,earned=0,independent=0,assisted=false,locked=false,current;
let timerId=null,startedAt=null,elapsed=0;
function formatTime(ms){const sec=Math.floor(ms/1000);return `${String(Math.floor(sec/60)).padStart(2,'0')}:${String(sec%60).padStart(2,'0')}`;}
function updateTimer(){if(startedAt!==null)elapsed=Math.max(0,Date.now()-startedAt);const el=document.querySelector('#timer');if(el)el.textContent=`Time ${formatTime(elapsed)}`;}
function stopTimer(){if(timerId!==null){updateTimer();clearInterval(timerId);timerId=null;}startedAt=null;}
function gradeFor(score){return ['D','C','B','B+','A','A+'][Math.max(0,Math.min(5,score))];}
function renderEquation(q){if(q.kind==='three')return `<div class="vertical-equation" role="math" aria-label="${q.a} plus ${q.b} minus ${q.c} equals what?"><div class="vertical-row"><span></span><span>${q.a}</span></div><div class="vertical-row"><span>+</span><span>${q.b}</span></div><div class="vertical-row"><span>&minus;</span><span>${q.c}</span></div><div class="vertical-result">?</div></div>`;if(['tens','carry','borrow'].includes(q.kind))return `<div class="vertical-equation" role="math" aria-label="${q.a} ${q.op==='+'?'plus':'minus'} ${q.b} equals what?"><div class="vertical-row"><span></span><span>${q.a}</span></div><div class="vertical-row"><span>${q.op}</span><span>${q.b}</span></div><div class="vertical-result">?</div></div>`;return `<div class="equation">${q.equation}</div>`;}
function updateStars(){document.querySelector('#stars').textContent=stars;save('garden-stars',stars);}
function pony(small=false){return `<svg class="pony ${small?'pony-small':''}" viewBox="0 0 260 240" aria-hidden="true" focusable="false"><ellipse cx="126" cy="222" rx="85" ry="9" fill="#72a8b2" opacity=".2"/><g class="pony-body"><path class="pony-tail" d="M73 137C22 100 14 162 36 192C23 156 61 196 65 162C41 179 45 134 73 151" fill="#aa73df" stroke="#8256b0" stroke-width="4" stroke-linejoin="round"/><path d="M86 165L80 210Q80 220 94 218L106 175M139 173L147 210Q148 220 161 216L161 166" fill="#d894c6" stroke="#a4619b" stroke-width="4" stroke-linejoin="round"/><ellipse cx="117" cy="151" rx="58" ry="40" fill="#f5b9df" stroke="#a4619b" stroke-width="4"/><path class="pony-leg" d="M78 168L67 207Q64 219 80 219L97 177M133 176L129 208Q129 222 145 219L154 169" fill="#f5b9df" stroke="#a4619b" stroke-width="4" stroke-linejoin="round"/><path d="M67 207L82 210L80 219L68 218ZM129 209L145 210L145 219L131 218Z" fill="#8c5cb8"/><path d="M144 154C131 123 148 89 166 82L203 110L183 158" fill="#f5b9df" stroke="#a4619b" stroke-width="4"/><path class="pony-mane" d="M165 77C131 77 125 100 135 120C116 123 126 151 139 153C130 164 142 182 157 171C145 149 176 151 161 127C181 122 164 105 177 98" fill="#ac79e2" stroke="#8256b0" stroke-width="4"/><path d="M177 70L174 35Q194 41 197 72" fill="#f5b9df" stroke="#a4619b" stroke-width="4"/><path d="M182 64L182 45L191 65" fill="#e58db9"/><path d="M190 70L209 45Q218 65 211 85" fill="#f5b9df" stroke="#a4619b" stroke-width="4"/><path d="M174 72C207 62 224 86 221 110L239 123Q248 145 225 153L195 147Q167 139 162 113Q155 86 174 72" fill="#f5b9df" stroke="#a4619b" stroke-width="4"/><ellipse cx="226" cy="136" rx="20" ry="14" fill="#ffd9e7"/><path class="pony-fringe" d="M163 83C145 54 198 48 211 71C223 73 223 95 211 104L202 82Q189 108 169 98L180 79Z" fill="#ab78e0" stroke="#8256b0" stroke-width="4" stroke-linejoin="round"/><ellipse class="pony-eye" cx="202" cy="109" rx="10" ry="14" fill="#49375e"/><ellipse cx="205" cy="105" rx="3.5" ry="5" fill="white"/><path d="M194 98L189 94M198 96L195 90" fill="none" stroke="#49375e" stroke-width="3" stroke-linecap="round"/><ellipse cx="190" cy="128" rx="9" ry="5" fill="#e889ba"/><circle cx="236" cy="131" r="2.5" fill="#a4619b"/><path d="M225 143Q233 147 239 140" fill="none" stroke="#a4619b" stroke-width="2.5" stroke-linecap="round"/><path d="M96 137L100 147L111 148L103 155L106 166L96 160L86 166L89 155L81 148L92 147Z" fill="#ffed92" stroke="#e0b74d" stroke-width="2"/></g><g class="pony-sparkles" fill="#edb640"><path d="M42 54L46 64L56 68L46 72L42 82L38 72L28 68L38 64Z"/><path d="M233 37L236 44L243 47L236 50L233 57L230 50L223 47L230 44Z"/></g></svg>`;}
const worldIcons=['&#127822;','&#127752;','&#128640;','&#11088;','&#127984;','&#128269;','&#128142;','&#127942;'];
const locations=['Apple Orchard','Rainbow River','Rocket Ridge','Starlight Hill','Castle Cove','Mystery Forest','Crystal Cave','Treasure Island'];
function renderMap(){return `<section class="adventure-map" aria-label="Choose a level on the adventure map"><div class="map-heading"><span aria-hidden="true">&#129517;</span><div><h2>Meryama's adventure island</h2><p>Tap a place to start exploring. Every location is open!</p></div></div><div class="map-land"><svg class="map-route" viewBox="0 0 1000 1000" preserveAspectRatio="none" aria-hidden="true"><path class="route-border" d="M250 125 H750 Q900 125 900 250 T750 375 H250 Q100 375 100 500 T250 625 H750 Q900 625 900 750 T750 875 H250"/><path class="route-dashes" d="M250 125 H750 Q900 125 900 250 T750 375 H250 Q100 375 100 500 T250 625 H750 Q900 625 900 750 T750 875 H250"/></svg><span class="map-tree tree-one" aria-hidden="true">&#127795;</span><span class="map-tree tree-two" aria-hidden="true">&#127796;</span>${levels.filter(l=>l.kind!=='multiply').map((l,i)=>`<button class="map-stop ${i===savedLevel?'map-current':''}" style="grid-row:${Math.floor(i/2)+1};grid-column:${[1,2,2,1,1,2,2,1][i]}" data-level="${i}" aria-label="Level ${i+1}: ${locations[i]}. ${l.description}" ${i===savedLevel?'aria-current="step"':''}><span class="map-island" aria-hidden="true">${worldIcons[i]}</span><span class="map-level">LEVEL ${i+1}${i<savedLevel?' &#10003;':''}</span><strong>${locations[i]}</strong><span class="map-skill">${l.title}</span><span class="map-play">${i===savedLevel?'You are here! Play':i<savedLevel?'Play again':'Explore'} &#10140;</span></button>`).join('')}</div></section>`;}
function home(){
stopTimer();updateStars();app.innerHTML=`<section class="hero"><div><div class="eyebrow">Meryama’s little world of wonders</div><h1>Ready, set,<br><em>let’s play!</em></h1><p>Hi Meryama! I’m Twinkle, your little pony buddy. Let’s solve puzzles and collect shiny stars!</p><span class="pill">5 little puzzles = 1 big adventure!</span></div><div class="garden"><span class="float-symbol symbol-one" aria-hidden="true">+</span><span class="float-symbol symbol-two" aria-hidden="true">7</span><span class="float-symbol symbol-three" aria-hidden="true">&#9733;</span><div class="buddy-bubble">You + me = a super team!</div>${pony()}<span class="garden-note">Meet Twinkle, your math buddy</span></div></section><section class="table-study"><h2>Times-table playground</h2><label for="study-table">Choose a table </label><select id="study-table">${Array.from({length:12},(_,i)=>`<option value="${i+1}">${i+1} times table</option>`).join('')}</select><div id="table-facts" class="table-facts"></div><button class="primary" id="practice-table">Let’s play this table! &#10140;</button></section><div class="section-head"><div><h2>Where shall we go?</h2><p>Collect stars as you play. Solve 4 on your own to level up!</p></div></div><section class="progress-panel"><span class="icon">🌱</span><div class="grow"><strong>Continue at level ${savedLevel+1}: ${levels[savedLevel].title}</strong><p>Your level saves on this browser. Tap any location on your map to play.</p><button class="primary" id="continue">Let’s go! →</button></div></section>${renderMap()}<p class="save-note">★ ${stars} stars collected · A star for every question you work through.</p>`;
const tableSelect=document.querySelector('#study-table');tableSelect.onchange=()=>showTable(Number(tableSelect.value));showTable(1);document.querySelector('#practice-table').onclick=()=>start(7+Number(tableSelect.value));
document.querySelector('#continue').onclick=()=>start(savedLevel);document.querySelectorAll('[data-level]').forEach(el=>el.onclick=()=>start(Number(el.dataset.level)));
}
function showTable(table){document.querySelector('#table-facts').innerHTML=Array.from({length:12},(_,i)=>`<div>${table} &times; ${i+1} = <strong>${table*(i+1)}</strong></div>`).join('');}
function start(index){stopTimer();selected=index;round=0;earned=0;independent=0;startedAt=Date.now();elapsed=0;question();timerId=setInterval(updateTimer,250);}
function question(){locked=false;assisted=false;current=generate(selected);app.innerHTML=`<div class="practice"><div class="topline"><button class="quiet" id="back">← Map</button><span>Level ${selected+1} · ${round+1} of 5</span><span class="timer" id="timer" role="timer" aria-label="Round time">Time ${formatTime(elapsed)}</span></div><div class="track"><div class="fill" style="width:${round*20}%"></div></div><div class="question-buddy">${pony(true)}<span>One little puzzle. You can do it!</span></div><div class="puzzle-stars" aria-label="${round} of 5 puzzles complete">${Array.from({length:5},(_,i)=>`<span class="${i<round?'star-earned':''}" aria-hidden="true">&#9733;</span>`).join('')}</div><section class="exercise"><div id="answer-effects" class="answer-effects" aria-hidden="true"></div><div class="eyebrow">${levels[selected].title}</div>${current.kind==='missing'?'<p>x is a mystery number. Find its value!</p>':''}${renderEquation(current)}<div class="answers">${current.choices.map(n=>`<button class="answer" data-value="${n}">${current.kind==='missing'?'x = ':''}${n}</button>`).join('')}</div><div class="feedback" role="status" aria-live="polite" id="feedback">${current.kind==='missing'?'What number is hiding behind x?':'Choose your answer.'}</div><button class="quiet" id="hintbutton">☀ Ask Twinkle for a clue</button><div id="hint"></div><button class="primary" id="next" hidden>Next question →</button></section></div>`;
document.querySelector('#back').onclick=home;document.querySelectorAll('[data-value]').forEach(el=>el.onclick=()=>check(el));document.querySelector('#hintbutton').onclick=hint;updateTimer();document.querySelector('#next').onclick=()=>{round++;round===5?finish():question();};}
function hint(){assisted=true;document.querySelector('#hint').innerHTML=`<div class="hint">${current.help}</div>`;}
function celebrateAnswer(correct){
const effects=document.querySelector('#answer-effects');
const buddy=document.querySelector('.question-buddy');
buddy.className='question-buddy '+(correct?'buddy-cheer':'buddy-encourage');
document.querySelector('.question-buddy>span').textContent=correct?'You did it! Pony high-five!':'Oopsie! You are learning. Try once more!';
effects.innerHTML=correct?`<div class="answer-party"><span class="party-sticker">${pony(true)}<strong>CORRECT!</strong></span>${Array.from({length:18},(_,i)=>`<i class="confetti-piece" style="--x:${5+(i*17)%90}%;--delay:${(i%5)*.07}s;--turn:${i*47}deg;--colour:${['#f4bb35','#e975ab','#8b70d9','#59bdb5'][i%4]}">${i%3===0?'&#9733;':''}</i>`).join('')}</div>`:`<div class="try-again-party">${pony(true)}<strong>WRONG ANSWER</strong><small>Try again, little explorer!</small></div>`;
}
function check(el){if(locked||el.disabled)return;if(Number(el.dataset.value)!==current.answer){assisted=true;el.classList.add('wrong');el.disabled=true;celebrateAnswer(false);document.querySelector('#feedback').textContent='Nice try, explorer! Twinkle has a little clue for you.';hint();return;}locked=true;earned++;if(round===4)stopTimer();stars++;if(!assisted)independent++;updateStars();el.classList.add('correct');celebrateAnswer(true);document.querySelectorAll('.answer').forEach(btn=>btn.disabled=true);document.querySelector('#feedback').textContent='★ Woohoo! You caught a shiny star!';document.querySelector('#hintbutton').hidden=true;document.querySelector('#next').hidden=false;document.querySelector('#next').textContent=round===4?'See how you grew →':'Next question →';}
function finish(){stopTimer();const grade=gradeFor(independent);const next=advance(selected,independent),promoted=next>selected,mastered=independent>=4&&selected===levels.length-1;savedLevel=Math.max(savedLevel,next);save('garden-level',savedLevel);app.innerHTML=`<section class="finish"><div class="celebration" aria-hidden="true">&#127881; &#11088; &#127881;</div>${pony(true)}<div class="big">${promoted||mastered?'🌻':'🌱'}</div><div class="eyebrow">Level ${selected+1} complete</div><h1>${promoted?'Ready to grow!':mastered?'Math superstar!':'Keep growing!'}</h1><div class="grade-badge" aria-label="Grade ${grade}">${grade}</div><p>You earned ${earned} stars and solved ${independent} of 5 questions without help.</p><p class="result-time">Round time: <strong>${formatTime(elapsed)}</strong></p><p class="grade-key">Grades use first-try answers without hints.<br>5/5: A+ | 4/5: A | 3/5: B+ | 2/5: B | 1/5: C | 0/5: D<br>Time is for practice and does not change your grade.</p><p>${promoted?`Next: level ${next+1}, ${levels[next].title}.`:mastered?'You reached the top level! Keep practicing with new challenges.':'Let’s practice this level again. Solve 4 without help to move up.'}</p><button class="primary" id="again">${promoted?'Try the next level →':'Practice with new questions →'}</button><br><button class="quiet" id="done">Back to my map</button></section>`;document.querySelector('#again').onclick=()=>start(next);document.querySelector('#done').onclick=home;}
document.querySelector('#home').onclick=e=>{e.preventDefault();home();};home();
